package cn.binbin.crm;

import java.nio.charset.*;
import java.nio.ByteBuffer;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.*;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class AttachmentService {
    public record Download(String fileName,String contentType,byte[] bytes) {}
    public record CleanupResult(int processed,int failed) {}
    private final NamedParameterJdbcTemplate db;private final DeliveryGuard guard;private final CustomerService customers;private final SalesService sales;private final ObjectStore storage;private final TransactionTemplate tx;private final TradeService trade;private final P3Base p3;private final ServiceDeskService desk;
    public AttachmentService(NamedParameterJdbcTemplate db,DeliveryGuard guard,CustomerService customers,SalesService sales,ObjectStore storage,TransactionTemplate tx,TradeService trade,P3Base p3,ServiceDeskService desk){this.db=db;this.guard=guard;this.customers=customers;this.sales=sales;this.storage=storage;this.tx=tx;this.trade=trade;this.p3=p3;this.desk=desk;}
    private static Map<String,Object> map(Object... values){return SaasService.parameters(values);}
    private Map<String,Object> params(AuthService.Actor a){return p3.params(a);}
    private static final String FROM=" FROM crm_attachment x JOIN crm_customer c ON c.tenant_id=x.tenant_id AND c.id=x.customer_id LEFT JOIN crm_ticket tk ON tk.tenant_id=x.tenant_id AND tk.id=x.ticket_id LEFT JOIN sys_tenant_member tm ON tm.tenant_id=tk.tenant_id AND tm.id=tk.owner_member_id LEFT JOIN sys_tenant_member tam ON tam.tenant_id=tk.tenant_id AND tam.id=tk.assignee_member_id LEFT JOIN crm_contract k ON k.tenant_id=x.tenant_id AND k.id=x.contract_id LEFT JOIN sys_tenant_member km ON km.tenant_id=k.tenant_id AND km.id=k.owner_member_id LEFT JOIN crm_opportunity o ON o.tenant_id=x.tenant_id AND o.id=coalesce(x.opportunity_id,k.opportunity_id) LEFT JOIN sys_tenant_member m ON m.tenant_id=x.tenant_id AND m.id=x.uploaded_by_member_id LEFT JOIN portal_account pa ON pa.id=x.uploaded_by_portal_account_id ";
    private static final String READ="x.tenant_id=:tenant AND "+CustomerService.READ+" AND (coalesce(x.opportunity_id,k.opportunity_id) IS NULL OR ("+SalesService.OP_READ+")) AND (x.contract_id IS NULL OR (:contractReader AND "+TradeService.own("k","km",false)+")) AND (x.receipt_id IS NULL OR :receiptReader) AND(x.ticket_id IS NULL OR(:ticketReader AND (:ticketReadAll OR tk.owner_member_id=:member OR tk.assignee_member_id=:member OR (:ticketReadDepartment AND (tm.department_id=:department OR tam.department_id=:department)))))";
    private static final String WRITE=CustomerService.WRITE+" AND (x.opportunity_id IS NULL OR "+SalesService.OP_WRITE+")";
    private Map<String,Object> record(AuthService.Actor a,UUID id){var p=params(a);p.put("id",id);var found=db.queryForList("SELECT x.*,c.customer_name,o.title AS opportunity_title,coalesce(m.display_name,pa.display_name||'（客户）') AS uploader_name,("+WRITE+") AS can_write"+FROM+"WHERE "+READ+" AND x.id=:id",p);if(found.isEmpty())throw ApiError.missing();var row=found.getFirst();trade.attachmentLink(a,(UUID)row.get("contract_id"),(UUID)row.get("receipt_id"),(UUID)row.get("customer_id"),(UUID)row.get("opportunity_id"),false);if(row.get("ticket_id")!=null)desk.ticket(a,(UUID)row.get("ticket_id"));return row;}
    private Map<String,Object> view(AuthService.Actor a,Map<String,Object> row){boolean canWrite=Boolean.TRUE.equals(row.get("can_write"));if(row.get("contract_id")!=null){try{trade.attachmentLink(a,(UUID)row.get("contract_id"),(UUID)row.get("receipt_id"),(UUID)row.get("customer_id"),(UUID)row.get("opportunity_id"),true);canWrite=true;}catch(ApiError e){canWrite=false;}}if(row.get("ticket_id")!=null){try{ticketLink(a,(UUID)row.get("ticket_id"),(UUID)row.get("customer_id"),true);canWrite=true;}catch(ApiError e){canWrite=false;}}canWrite=canWrite&&!trade.attachmentProtected(a,row);var copy=new LinkedHashMap<>(row);copy.remove("object_key");copy.put("can_write",canWrite&&a.deliveryAccess().attachmentWrite()&&a.tenant().subscriptionEnd().isAfter(Instant.now())&&"READY".equals(row.get("status")));return SaasService.view(copy);}
    public Map<String,Object> files(AuthService.Session s,int page,int size,String q,UUID customer,UUID contract,UUID receipt,UUID ticket){if(page<1||page>100000||size<1||size>100||q.length()>100)throw ApiError.bad("附件分页或搜索条件无效");return guard.scoped(s,"attachment",false,a->{if(customer!=null)customers.get(a,customer);if(ticket!=null)desk.ticket(a,ticket);if(contract!=null)trade.contract(a,contract);if(receipt!=null&&contract==null)throw ApiError.bad("请同时指定回款所属合同");var p=params(a);p.put("customer",customer);p.put("contract",contract);p.put("receipt",receipt);p.put("ticket",ticket);p.put("q",q.strip());p.put("limit",size);p.put("offset",((long)page-1)*size);String where=READ+" AND x.status='READY' AND(cast(:ticket AS uuid) IS NULL OR x.ticket_id=:ticket) AND (cast(:contract AS uuid) IS NULL OR x.contract_id=:contract) AND (cast(:receipt AS uuid) IS NULL OR x.receipt_id=:receipt) AND (cast(:customer AS uuid) IS NULL OR x.customer_id=:customer) AND (:q='' OR strpos(lower(x.file_name),lower(:q))>0 OR strpos(lower(c.customer_name),lower(:q))>0)";long total=db.queryForObject("SELECT count(*)"+FROM+"WHERE "+where,p,Long.class);var rows=db.queryForList("SELECT x.*,c.customer_name,o.title AS opportunity_title,coalesce(m.display_name,pa.display_name||'（客户）') AS uploader_name,("+WRITE+") AS can_write"+FROM+"WHERE "+where+" ORDER BY x.created_at DESC,x.id LIMIT :limit OFFSET :offset",p);return map("items",rows.stream().map(r->view(a,r)).toList(),"total",total,"page",page,"pageSize",size,"storageConfigured",storage.configured());});}
    private void links(AuthService.Actor a,UUID customer,UUID opportunity){if(!customers.get(a,customer).canWrite())throw ApiError.forbidden("无权修改关联客户附件");if(opportunity!=null){if(!a.businessAccess().opportunities().read())throw ApiError.forbidden("没有商机读取权限");var o=sales.opportunity(a,opportunity);if(!customer.equals(o.get("customerId")))throw ApiError.bad("商机不属于所选客户");if(!Boolean.TRUE.equals(o.get("canLink")))throw ApiError.forbidden("无权修改关联商机附件");}}
    private void ticketLink(AuthService.Actor a,UUID ticket,UUID customer,boolean write){var t=desk.ticket(a,ticket);if(customer==null||!customer.equals(t.get("customerId")))throw ApiError.bad("工单附件需关联该工单客户");if(write&&(!Boolean.TRUE.equals(t.get("canWrite"))||!Set.of("NEW","IN_PROGRESS","WAITING_CUSTOMER").contains(t.get("status"))))throw ApiError.forbidden("只可修改获准的处理中工单附件，结束后保留历史");}
    public static String filename(String original){String s=original==null?"":original.replace('\\','/');s=s.substring(s.lastIndexOf('/')+1).strip();if(s.isEmpty()||s.length()>200||s.chars().anyMatch(c->c<32||c==127))throw ApiError.bad("文件名无效");return s;}
    public static String fileType(String name,byte[] bytes){if(bytes.length<1||bytes.length>5242880)throw ApiError.bad("文件需在1字节至5MB之间");String n=name.toLowerCase(Locale.ROOT);
        if(n.endsWith(".png")&&bytes.length>=8&&Arrays.equals(Arrays.copyOf(bytes,8),new byte[]{(byte)137,80,78,71,13,10,26,10}))return "image/png";
        if((n.endsWith(".jpg")||n.endsWith(".jpeg"))&&bytes.length>=3&&(bytes[0]&255)==255&&(bytes[1]&255)==216&&(bytes[2]&255)==255)return "image/jpeg";
        if(n.endsWith(".pdf")&&bytes.length>=5&&new String(bytes,0,5,StandardCharsets.US_ASCII).equals("%PDF-"))return "application/pdf";
        if(n.endsWith(".txt")||n.endsWith(".csv")){try{var text=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes));if(text.toString().indexOf('\0')>=0)throw ApiError.bad("文本包含无效字符");return n.endsWith(".csv")?"text/csv":"text/plain";}catch(CharacterCodingException e){throw ApiError.bad("文本需为UTF-8编码");}}
        throw ApiError.bad("支持PNG、JPEG、PDF及UTF-8 TXT / CSV，文件内容需与格式一致");
    }
    private static String sha(byte[] data){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data));}catch(Exception e){throw new IllegalStateException(e);}}
    public Map<String,Object> upload(AuthService.Session s,UUID customer,UUID opportunity,UUID contract,UUID receipt,UUID ticket,String original,byte[] bytes,String key,UUID trace){String name=filename(original),type=fileType(name,bytes),digest=sha(bytes);if(!key.matches("[A-Za-z0-9_.:-]{1,100}"))throw ApiError.bad("请求编号无效");final UUID created=UUID.randomUUID();final String object=storage.key(s.tenantId(),created);boolean[] stored={false};
        try{return guard.scoped(s,"attachment",true,a->{if(ticket!=null){if(contract!=null||receipt!=null||opportunity!=null)throw ApiError.bad("工单附件不能绑定商机、合同或回款");ticketLink(a,ticket,customer,true);}else if(contract==null)links(a,customer,opportunity);else trade.attachmentLink(a,contract,receipt,customer,opportunity,true);var p=params(a);p.put("op","attachment.upload");p.put("key",key);p.put("hash",Crypto.hash(ticket!=null?customer+":"+ticket+":"+name+":"+digest:contract==null&&receipt==null?customer+":"+opportunity+":"+name+":"+digest:customer+":"+opportunity+":"+contract+":"+receipt+":"+name+":"+digest));db.update("INSERT INTO sys_idempotency_request(tenant_id,member_id,operation,request_key,request_hash) VALUES(:tenant,:member,:op,:key,:hash) ON CONFLICT DO NOTHING",p);var prior=db.queryForMap("SELECT request_hash,result_id FROM sys_idempotency_request WHERE tenant_id=:tenant AND member_id=:member AND operation=:op AND request_key=:key FOR UPDATE",p);if(!p.get("hash").equals(prior.get("request_hash")))throw ApiError.conflict("相同请求编号不能上传不同文件");if(prior.get("result_id")!=null)return view(a,record(a,(UUID)prior.get("result_id")));
            var quota=db.queryForMap("SELECT t.attachment_bytes,p.storage_limit_bytes FROM sys_tenant t JOIN sys_plan p ON p.id=t.plan_id WHERE t.id=:tenant",p);if(((Number)quota.get("attachment_bytes")).longValue()+bytes.length>((Number)quota.get("storage_limit_bytes")).longValue())throw new ApiError(org.springframework.http.HttpStatus.CONFLICT,"ATTACHMENT_QUOTA_EXCEEDED","附件容量已达到套餐上限");
            storage.put(object,bytes,type);stored[0]=true;p.putAll(map("id",created,"customer",customer,"opportunity",opportunity,"contract",contract,"receipt",receipt,"ticket",ticket,"file",name,"type",type,"size",bytes.length,"digest",digest,"object",object));db.update("INSERT INTO crm_attachment(id,tenant_id,customer_id,opportunity_id,contract_id,receipt_id,ticket_id,file_name,content_type,size_bytes,sha256,object_key,uploaded_by_member_id) VALUES(:id,:tenant,:customer,:opportunity,:contract,:receipt,:ticket,:file,:type,:size,:digest,:object,:member)",p);db.update("UPDATE sys_idempotency_request SET result_id=:id WHERE tenant_id=:tenant AND member_id=:member AND operation=:op AND request_key=:key",p);DataService.audit(db,a,"ATTACHMENT_UPLOADED","ATTACHMENT",created,0,trace);return view(a,record(a,created));
        });}catch(RuntimeException e){if(stored[0]){try{storage.delete(object);}catch(Exception ignored){queue(s.tenantId(),object);}}throw e;}
    }
    private void queue(UUID tenant,String key){tx.executeWithoutResult(status->{db.queryForObject("SELECT set_config('crm.tenant_id',:tenant,true)",map("tenant",tenant.toString()),String.class);db.update("INSERT INTO sys_object_cleanup(id,tenant_id,object_key) VALUES(:id,:tenant,:key) ON CONFLICT(object_key) DO NOTHING",map("id",UUID.randomUUID(),"tenant",tenant,"key",key));});}
    public Download download(AuthService.Session s,UUID id,UUID trace){return guard.scoped(s,"attachment",false,a->{var r=record(a,id);if(!"READY".equals(r.get("status")))throw ApiError.missing();byte[] data=storage.get((String)r.get("object_key"));if(data.length!=((Number)r.get("size_bytes")).longValue()||!sha(data).equals(r.get("sha256")))throw new ApiError(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,"ATTACHMENT_INTEGRITY_ERROR","文件校验未通过，请联系管理员");DataService.audit(db,a,"ATTACHMENT_DOWNLOADED","ATTACHMENT",id,((Number)r.get("version")).longValue(),trace);return new Download((String)r.get("file_name"),(String)r.get("content_type"),data);});}
    public void delete(AuthService.Session s,UUID id,long version,UUID trace){guard.scoped(s,"attachment",true,a->{var r=record(a,id);if(!"READY".equals(r.get("status")))return null;if(!Boolean.TRUE.equals(view(a,r).get("canWrite")))throw ApiError.forbidden("无权删除此附件，已签合同及回款凭证需保留历史");if(((Number)r.get("version")).longValue()!=version)throw ApiError.conflict("附件已变化，请刷新");db.update("UPDATE crm_attachment SET status='DELETED',deleted_at=now(),version=version+1 WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));db.update("INSERT INTO sys_object_cleanup(id,tenant_id,object_key) VALUES(:id,:tenant,:key) ON CONFLICT(object_key) DO NOTHING",map("id",UUID.randomUUID(),"tenant",a.tenant().id(),"key",r.get("object_key")));DataService.audit(db,a,"ATTACHMENT_DELETED","ATTACHMENT",id,version+1,trace);return null;});}
    public CleanupResult cleanup(UUID tenant){if(!storage.configured())return new CleanupResult(0,0);return tx.execute(status->{db.queryForObject("SELECT set_config('crm.tenant_id',:tenant,true)",map("tenant",tenant.toString()),String.class);var rows=db.queryForList("SELECT id,object_key,attempts FROM sys_object_cleanup WHERE tenant_id=:tenant AND completed_at IS NULL AND next_attempt_at<=now() ORDER BY created_at,id LIMIT 50 FOR UPDATE SKIP LOCKED",map("tenant",tenant));int count=0,failed=0;for(var r:rows){try{storage.delete((String)r.get("object_key"));db.update("UPDATE sys_object_cleanup SET completed_at=now(),error_code=NULL WHERE id=:id",map("id",r.get("id")));count++;}catch(Exception e){failed++;int attempts=((Number)r.get("attempts")).intValue()+1;db.update("UPDATE sys_object_cleanup SET attempts=:attempts,error_code='STORAGE_DELETE_FAILED',next_attempt_at=now()+make_interval(secs=>:delay) WHERE id=:id",map("id",r.get("id"),"attempts",attempts,"delay",Math.min(3600,30*(1<<Math.min(attempts,6)))));}}return new CleanupResult(count,failed);});}
}
